 #include <QPointer>
@@ -18,6 +19,9 @@ namespace KWin
 {

 static const int s_version = 1;
+static const int s_optionsVersion = 1;
+
+class XdgActivationTokenOptionsV1Interface;

 class XdgActivationTokenV1Interface : public QtWaylandServer::xdg_activation_token_v1
 {
@@ -28,6 +32,12 @@ public:
         , m_client(client)
     {
     }
+    ~XdgActivationTokenV1Interface() override;
+
+    static XdgActivationTokenV1Interface *get(struct ::wl_resource *resource);
+
+    XdgActivationTokenOptionsV1Interface *m_options = nullptr;
+    bool m_startupFeedback = true;

 protected:
     void xdg_activation_token_v1_set_serial(Resource *resource, uint32_t serial, struct ::wl_resource *seat) override;
@@ -46,6 +56,56 @@ protected:
     ClientConnection *const m_client;
 };

+class XdgActivationTokenOptionsV1Interface : public QtWaylandServer::kde_xdg_activation_token_options_v1
+{
+public:
+    XdgActivationTokenOptionsV1Interface(XdgActivationTokenV1Interface *token, wl_client *client, uint32_t id)
+        : QtWaylandServer::kde_xdg_activation_token_options_v1(client, id, s_optionsVersion)
+        , m_token(token)
+    {
+        m_token->m_options = this;
+    }
+    ~XdgActivationTokenOptionsV1Interface() override
+    {
+        if (m_token) {
+            m_token->m_options = nullptr;
+        }
+    }
+
+    XdgActivationTokenV1Interface *m_token;
+
+protected:
+    void kde_xdg_activation_token_options_v1_set_no_startup_feedback(Resource *resource) override
+    {
+        if (m_token) {
+            m_token->m_startupFeedback = false;
+        }
+    }
+    void kde_xdg_activation_token_options_v1_destroy(Resource *resource) override
+    {
+        wl_resource_destroy(resource->handle);
+    }
+    void kde_xdg_activation_token_options_v1_destroy_resource(Resource *resource) override
+    {
+        delete this;
+    }
+};
+
+XdgActivationTokenV1Interface::~XdgActivationTokenV1Interface()
+{
+    if (m_options) {
+        m_options->m_token = nullptr;
