+
+XdgActivationTokenV1Interface *XdgActivationTokenV1Interface::get(struct ::wl_resource *resource)
+{
+    if (auto tokenResource = QtWaylandServer::xdg_activation_token_v1::Resource::fromResource(resource)) {
+        return static_cast<XdgActivationTokenV1Interface *>(tokenResource->xdg_activation_token_v1_object);
+    }
+    return nullptr;
+}
+
 void XdgActivationTokenV1Interface::xdg_activation_token_v1_set_serial(Resource *resource, uint32_t serial, struct ::wl_resource *seat)
 {
     m_serial = serial;
@@ -66,7 +126,7 @@ void XdgActivationTokenV1Interface::xdg_activation_token_v1_commit(Resource *res
 {
     QString token;
     if (m_creator) {
-        token = m_creator(m_client, m_surface, m_serial, SeatInterface::get(m_seat), m_appId);
+        token = m_creator(m_client, m_surface, m_serial, SeatInterface::get(m_seat), m_appId, m_startupFeedback);
     }

     m_committed = true;
@@ -86,12 +146,41 @@ void XdgActivationTokenV1Interface::xdg_activation_token_v1_destroy_resource(Res
     delete this;
 }

+class XdgActivationOptionsV1Interface : public QtWaylandServer::kde_xdg_activation_options_v1
+{
+public:
+    explicit XdgActivationOptionsV1Interface(Display *display)
+        : QtWaylandServer::kde_xdg_activation_options_v1(*display, s_optionsVersion)
+    {
+    }
+
+protected:
+    void kde_xdg_activation_options_v1_get_token_options(Resource *resource, uint32_t id, struct ::wl_resource *token) override
+    {
+        auto tokenInterface = XdgActivationTokenV1Interface::get(token);
+        if (!tokenInterface) {
+            wl_resource_post_error(resource->handle, error_invalid_token, "the token isn't a valid xdg_activation_token_v1");
+            return;
+        }
+        if (tokenInterface->m_options) {
+            wl_resource_post_error(resource->handle, error_already_constructed, "the token already has an options object");
+            return;
+        }
+        new XdgActivationTokenOptionsV1Interface(tokenInterface, resource->client(), id);
+    }
+    void kde_xdg_activation_options_v1_destroy(Resource *resource) override
+    {
+        wl_resource_destroy(resource->handle);
+    }
+};
+
 class XdgActivationV1InterfacePrivate : public QtWaylandServer::xdg_activation_v1
 {
 public:
     XdgActivationV1InterfacePrivate(Display *display, XdgActivationV1Interface *q)
         : QtWaylandServer::xdg_activation_v1(*display, s_version)
         , q(q)
+        , m_options(display)
     {
     }

@@ -103,6 +192,7 @@ protected:
 public:
     XdgActivationV1Interface::CreatorFunction m_creator;
     XdgActivationV1Interface *const q;
+    XdgActivationOptionsV1Interface m_options;
 };

 void XdgActivationV1InterfacePrivate::xdg_activation_v1_get_activation_token(Resource *resource, uint32_t id)
