+++ b/src/xdgactivationv1.h
@@ -34,12 +34,12 @@ public:

     QString requestPrivilegedToken(SurfaceInterface *surface, uint serial, SeatInterface *seat, const QString &appId)
     {
-        return requestToken(true, surface, serial, seat, appId);
+        return requestToken(true, surface, serial, seat, appId, true);
     }
     void activateSurface(SurfaceInterface *surface, const QString &token);

 private:
-    QString requestToken(bool isPrivileged, SurfaceInterface *surface, UInt32Serial serial, SeatInterface *seat, const QString &appId);
