 .../wayland/waylandxdgactivationv1.cpp        | 35 +++++++++++++++++--
 .../wayland/waylandxdgactivationv1_p.h        | 18 +++++++++-
 src/platforms/wayland/windowsystem.cpp        |  7 +++-
 src/platforms/wayland/windowsystem.h          |  3 +-
 9 files changed, 104 insertions(+), 6 deletions(-)

diff --git a/CMakeLists.txt b/CMakeLists.txt
index ce27241..b165a51 100644
--- a/CMakeLists.txt
+++ b/CMakeLists.txt
