     find_package(Qt6WaylandClient ${REQUIRED_QT_VERSION} CONFIG REQUIRED)
     find_package(WaylandProtocols 1.46 REQUIRED)
-    find_package(PlasmaWaylandProtocols REQUIRED)
+    find_package(PlasmaWaylandProtocols 1.24.0 REQUIRED)
     check_cxx_source_compiles("
         #include <fcntl.h>
         #include <sys/mman.h>
diff --git a/src/kwaylandextras.cpp b/src/kwaylandextras.cpp
