@@ -142,6 +142,14 @@ QFuture<QString> KWaylandExtras::xdgActivationToken(QWindow *window, const QStri
     return xdgActivationToken(window, lastInputSerial(window), appId);
 }

+QFuture<QString> KWaylandExtras::xdgActivationToken(QWindow *window, const QString &appId, XdgActivationTokenOptions options)
+{
+    if (auto dv6 = dynamic_cast<KWindowSystemPrivateV6 *>(KWindowSystem::d_func())) {
+        return dv6->xdgActivationToken(window, lastInputSerial(window), appId, options);
+    }
+    return xdgActivationToken(window, appId);
+}
+
 void KWaylandExtras::setXdgToplevelTag(QWindow *window, const QString &tag)
 {
     if (auto dv4 = dynamic_cast<KWindowSystemPrivateV4 *>(KWindowSystem::d_func())) {
diff --git a/src/kwaylandextras.h b/src/kwaylandextras.h
index de98f53..97b7f6f 100644
