@@ -31,6 +31,21 @@ public:
      */
     static KWaylandExtras *self();

+    /*!
+     * \enum KWaylandExtras::XdgActivationTokenOption
+     *
+     * Options for xdgActivationToken().
+     *
+     * \value NoStartupFeedback Ask the compositor not to show startup feedback (such as a busy cursor) for the token.
+     * Use it when the token is passed to an application that is already running and may not show any window.
+     *
+     * \since 6.33
+     */
+    enum class XdgActivationTokenOption {
+        NoStartupFeedback = 0x1,
+    };
+    Q_DECLARE_FLAGS(XdgActivationTokenOptions, XdgActivationTokenOption)
+
 #if KWINDOWSYSTEM_ENABLE_DEPRECATED_SINCE(6, 19)
     /*!
      * Requests an xdg_activation_v1 token for a specific window \a win with the given \a app_id.
@@ -114,6 +129,18 @@ public:
      */
     static QFuture<QString> xdgActivationToken(QWindow *window, const QString &appId);

+    /*!
+     * Requests an xdg_activation_v1 token for a specific window \a window with the given \a appId and \a options.
+     * The last received input serial will be used to request the token.
+     *
+     * Options the compositor doesn't support are ignored.
+     *
+     * \note No xdgActivationTokenArrived() signal will be emitted for this token. Use the QFuture instead.
+     *
+     * \since 6.33
+     */
+    static QFuture<QString> xdgActivationToken(QWindow *window, const QString &appId, XdgActivationTokenOptions options);
+
     /*!
      * Assigns the specified \a tag to the given \a window.
      *
@@ -158,4 +185,6 @@ private:
     void *d;
 };

+Q_DECLARE_OPERATORS_FOR_FLAGS(KWaylandExtras::XdgActivationTokenOptions)
+
 #endif
