         ${PLASMA_WAYLAND_PROTOCOLS_DIR}/shadow.xml
diff --git a/src/platforms/wayland/waylandxdgactivationv1.cpp b/src/platforms/wayland/waylandxdgactivationv1.cpp
index 5ae4d28..3daa625 100644
--- a/src/platforms/wayland/waylandxdgactivationv1.cpp
+++ b/src/platforms/wayland/waylandxdgactivationv1.cpp
@@ -26,8 +26,11 @@ WaylandXdgActivationV1 *WaylandXdgActivationV1::self()
     return instance;
 }

-WaylandXdgActivationTokenV1 *
-WaylandXdgActivationV1::requestXdgActivationToken(wl_seat *seat, struct ::wl_surface *surface, uint32_t serial, const QString &app_id)
+WaylandXdgActivationTokenV1 *WaylandXdgActivationV1::requestXdgActivationToken(wl_seat *seat,
+                                                                               struct ::wl_surface *surface,
+                                                                               uint32_t serial,
+                                                                               const QString &app_id,
+                                                                               KWaylandExtras::XdgActivationTokenOptions options)
 {
     auto wl = get_activation_token();
     auto provider = new WaylandXdgActivationTokenV1;
@@ -41,8 +44,36 @@ WaylandXdgActivationV1::requestXdgActivationToken(wl_seat *seat, struct ::wl_sur

     if (seat)
         provider->set_serial(serial, seat);
+
+    if (options & KWaylandExtras::XdgActivationTokenOption::NoStartupFeedback) {
+        if (auto tokenOptions = WaylandXdgActivationOptionsV1::self(); tokenOptions->isActive()) {
+            QtWayland::kde_xdg_activation_token_options_v1 opts(tokenOptions->get_token_options(wl));
+            opts.set_no_startup_feedback();
+            opts.destroy();
+        }
+    }
+
     provider->commit();
     return provider;
 }

+WaylandXdgActivationOptionsV1::WaylandXdgActivationOptionsV1()
+    : QWaylandClientExtensionTemplate<WaylandXdgActivationOptionsV1>(1)
+{
+    initialize();
+}
+
+WaylandXdgActivationOptionsV1::~WaylandXdgActivationOptionsV1()
+{
+    if (isQpaAlive() && isActive()) {
+        destroy();
+    }
+}
+
+WaylandXdgActivationOptionsV1 *WaylandXdgActivationOptionsV1::self()
+{
+    static WaylandXdgActivationOptionsV1 *instance = new WaylandXdgActivationOptionsV1;
+    return instance;
+}
+
 #include "moc_waylandxdgactivationv1_p.cpp"
