+    WaylandXdgActivationTokenV1 *requestXdgActivationToken(wl_seat *seat,
+                                                           struct ::wl_surface *surface,
+                                                           uint32_t serial,
+                                                           const QString &app_id,
+                                                           KWaylandExtras::XdgActivationTokenOptions options = {});

 private:
     WaylandXdgActivationV1();
 };

+class WaylandXdgActivationOptionsV1 : public QWaylandClientExtensionTemplate<WaylandXdgActivationOptionsV1>, public QtWayland::kde_xdg_activation_options_v1
+{
+public:
+    ~WaylandXdgActivationOptionsV1() override;
