From b5da5f9e516f82dc3dcfa6df18bbe98b1344d809 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:59:35 +0100
Subject: [PATCH] libnotificationmanager: no launch feedback for notification
 actions

Notification actions go to an app that is already running, but their
activation token was requested like one for a launch, so KWin showed
launch feedback. Request the token with NoStartupFeedback instead.

BUG: 509169
---
 libnotificationmanager/server.cpp | 5 +++++
 1 file changed, 5 insertions(+)

diff --git a/libnotificationmanager/server.cpp b/libnotificationmanager/server.cpp
index 65490958f5..aafe53227f 100644
--- a/libnotificationmanager/server.cpp
+++ b/libnotificationmanager/server.cpp
@@ -17,6 +17,7 @@
 #include <KWaylandExtras>
 #include <KWindowSystem>
 #include <QDebug>
+#include <kwindowsystem_version.h>

 using namespace NotificationManager;

@@ -77,7 +78,11 @@ void Server::invokeAction(uint notificationId,
                           QWindow *window)
 {
     if (KWindowSystem::isPlatformWayland()) {
+#if KWINDOWSYSTEM_VERSION >= QT_VERSION_CHECK(6, 33, 0)
+        auto tokenFuture = KWaylandExtras::xdgActivationToken(window, xdgActivationAppId, KWaylandExtras::XdgActivationTokenOption::NoStartupFeedback);
+#else
         auto tokenFuture = KWaylandExtras::xdgActivationToken(window, xdgActivationAppId);
+#endif
         tokenFuture.then(this, [this, actionName, notificationId, behavior](const QString &token) {
             Q_EMIT d->ActivationToken(notificationId, token);
             Q_EMIT d->ActionInvoked(notificationId, actionName);
